"""Bounded online LLM routing around an audited strong memory/fine-tuned prior."""
from common import *
from hybrid_router import KNOWLEDGE
from enriched_memory import enriched
from concurrent.futures import ThreadPoolExecutor,as_completed
import sys

def run(level,part,thinking=False):
 name=f'20261105_strongagent_l{level}_{part}_think{int(thinking)}_mse';out=ROOT/'runs'/name;out.mkdir(exist_ok=True);(out/'requests').mkdir(exist_ok=True);subprocess.run([sys.executable,str(ROOT/'src/preflight.py'),'--root',str(ROOT),'--run-name',name],check=True)
 cfg={'engine':'strong_agent_v1','level':level,'part':part,'thinking':thinking,'tools':['20261105_reloadedft_lr5e7_mse','20261105_enrichedmemory_both_mse'],'default_ft_weight':.7,'bounds':[.55,.85],'cadence':24,'local_workers':2,'temperature_note':'thinking provider may ignore temperature','code_revision':git_head()};save_json(out/'config.json',cfg)
 z=np.load(RUN/'cache/trainval_z.npy');manifest=json.loads((RUN/'cache/window_manifest.json').read_text());ca=np.load(RUN/'cache/dense_chronos_train.npz');ta=np.load(RUN/'cache/dense_timesfm_train.npz');origins=ca['origins'];tx,ty=windows(z[:8640],origins);err=ty-(ca['predictions']+ta['predictions'])/2;idx={int(t):i for i,t in enumerate(origins)};neighbors=json.loads((ROOT/'runs/20261105_enrichedmemory_both_mse/neighbor_origins.json').read_text());cards=json.loads((ROOT/'src/knowledge_cards_v2.json').read_text())['facts'];results={};start=time.time()
 for split in (('dev','confirm') if part=='screen' else ('val',)):
  ts=manifest[split];ft=np.load(ROOT/'runs'/cfg['tools'][0]/f'{split}_predictions.npy');mem=np.load(ROOT/'runs'/cfg['tools'][1]/f'{split}_predictions.npy');weights=np.full((len(ts),7),.7);step=24 if split=='val' else 1;records=[]
  def one(i):
   guard(900);t=ts[i];x=z[t-512:t];s=np.maximum(x.std(0),.05);a=np.clip((x[-168:]-x[-168:].mean(0))/np.maximum(x[-168:].std(0),.05),-10,10);chosen=[idx[int(v)] for v in neighbors[split][i]];assert all(origins[j]+64<=t-512 for j in chosen)
   info={'columns':COLS,'default_ft_weight':.7,'history_mean24_96_512':[x[-k:].mean(0).round(3).tolist() for k in (24,96,512)],'history_std':s.round(3).tolist(),'change_last24_vs_previous24':(x[-24:].mean(0)-x[-48:-24].mean(0)).round(3).tolist(),'skew168':(a**3).mean(0).round(3).tolist(),'excess_kurtosis168':((a**4).mean(0)-3).round(3).tolist(),'acf24':[round(float(np.corrcoef(x[:-24,j],x[24:,j])[0,1]),3) if min(x[:-24,j].std(),x[24:,j].std())>1e-8 else None for j in range(7)],'forecast_block_means8h':{'finetuned':ft[i].reshape(8,8,7).mean(1).round(3).tolist(),'memory':mem[i].reshape(8,8,7).mean(1).round(3).tolist()},'forecast_std':{'finetuned':ft[i].std(0).round(3).tolist(),'memory':mem[i].std(0).round(3).tolist()}}
   system='You control a conservative blend of two audited numeric forecasting tools. Return ONLY JSON {"ft_weight":[7 numbers in [.55,.85]]}. Column order '+','.join(COLS)+'. Prediction=ft_weight*finetuned+(1-ft_weight)*memory for each variable and all64 future hours. Default weight .7. The finetuned tool is Chronos2 adapted only on official training, outputs average nine quantiles, explicitly eval-mode. The memory tool combines DLinear and two frozen pretrained tools, plus errors retrieved from1009 training cases using history shape, forecast uncertainty, higher moments and cross-variable correlations. It aligns residuals by24-hour phase, coefficient.75, clips corrections to .5 historical std. Matching history is not proof of matching future errors. No current future truth is given. Full-trained tool errors on training would be biased, so none are supplied. Do not guess error rates or treat smoother forecasts as automatically better. Deviate from .7 only with specific evidence; you may keep .7. All inputs in fixed train-standardized units. Weights are held24 rolling origins while forecasts update hourly.'
   if level>=1:system+='\n'+KNOWLEDGE
   if level>=2:
    wanted={'ETT_FIELDS','CHANNEL_SPECIFIC_SEASONALITY','LEVEL_VS_CHANGE','TRAIN_SOFT_BALANCE','THERMAL_LAG','NEGATIVE_RECORDED_VALUES'};info['knowledge_cards']=[v for v in cards if v['id'] in wanted];info['retrieved_cases']=[{'origin':int(origins[j]),'pretrained_mean_error_actual_minus_predicted':err[j].mean(0).round(3).tolist(),'pretrained_early16_error':err[j,:16].mean(0).round(3).tolist(),'pretrained_late16_error':err[j,-16:].mean(0).round(3).tolist(),'history_mean_difference':(tx[j].mean(0)-x.mean(0)).round(3).tolist()} for j in chosen];info['scope_warning']='Case errors refer to frozen pretrained tools before correction, NOT to the fine-tuned tool or the final corrected memory forecast. Do not interpret them as comparative MSE. Pretraining overlap not fully audited.';system+=' First question whether the retrieved error direction is stable and matches the query regime; then whether the correction is already present in the memory forecast. Avoid double-counting correction or confusing physical prior with observation. Output only final coefficients.'
   msgs=[{'role':'system','content':system},{'role':'user','content':json.dumps(info,ensure_ascii=False,separators=(',',':'))}];prefix=f'{split}_{i:04d}';save_json(out/'requests'/(prefix+'.json'),msgs)
   try:
    ans=api(msgs,10000 if thinking else 500,thinking='enabled' if thinking else 'disabled',reasoning_effort='low' if thinking else None);save_json(out/'requests'/(prefix+'_response.json'),ans);w=np.asarray(parse_json(ans['content'])['ft_weight'],float);assert w.shape==(7,) and np.isfinite(w).all() and ((w>=.55)&(w<=.85)).all();status='ok'
   except Exception as e:w=np.full(7,.7);status='fallback_'+type(e).__name__
   return i,w,status
  with ThreadPoolExecutor(max_workers=2) as pool:
   for f in as_completed([pool.submit(one,i) for i in range(0,len(ts),step)]):
    i,w,status=f.result();weights[i:i+step]=w;records.append({'index':i,'origin':ts[i],'status':status});print(name,split,i,status,flush=True)
  p=(weights[:,None]*ft+(1-weights[:,None])*mem).astype(np.float32);m=metric(p,np.load(RUN/'cache'/f'{split}_targets.npy'));m['fallback_decisions']=sum(r['status']!='ok' for r in records);m['decisions']=len(records);results[split]=m;np.save(out/f'{split}_predictions.npy',p);np.save(out/f'{split}_weights.npy',weights);save_json(out/f'{split}_decisions.json',records);save_json(out/'partial_metrics.json',results)
 save_json(out/'metrics.json',{'candidate':name,'metrics':results,'status':'evaluated','elapsed_seconds':time.time()-start});print(name,{s:m['mse'] for s,m in results.items()},flush=True)
if __name__=='__main__':run(int(sys.argv[1]),sys.argv[2],bool(int(sys.argv[3])) if len(sys.argv)>3 else False)
